      ],
      "attributes": {
        "context": "real_world",
        "treatment": "illustrative"
      },
      "contextualization": {
        "value": "everyday",
        "evidence": [
          {
            "excerpt_index": 0,
            "quote": "Ton corps brûle du glucose grâce à des réactions d'oxydoréduction pour te donner de l'énergie."
